-- Replace Raffles Marina Optimist Regatta 2025 with the official Sailwave
-- provisional results (6 July 2025).
-- Gold: 8 races, one discard, 80 entries. Silver: 6 races, one discard, 51 entries.
-- The older overall-only RM Jul 25 sheets are removed so the regatta is not scored twice.

drop table if exists public._rmor2025_load;

create table public._rmor2025_load (
  fleet text not null,
  pos integer not null,
  final_rank integer not null,
  sailor_id uuid not null,
  sex text not null,
  nett real not null,
  total real not null,
  races jsonb not null
);


do $$
declare
  bad integer;
  missing integer;
  distinct_sailors integer;
begin
  select count(*) into bad
  from public._rmor2025_load row
  where jsonb_array_length(row.races) <> case when row.fleet = 'Silver' then 6 else 8 end
     or (select count(*) from jsonb_array_elements(row.races) item where (item->>'discarded')::boolean) <> 1
     or (select sum((item->>'score')::real) from jsonb_array_elements(row.races) item) <> row.total
     or (select sum((item->>'score')::real) from jsonb_array_elements(row.races) item where not (item->>'discarded')::boolean) <> row.nett;
  select count(*) into missing
  from public._rmor2025_load source
  left join public.sailors sailor on sailor.id = source.sailor_id
  where sailor.id is null;
  select count(distinct sailor_id) into distinct_sailors from public._rmor2025_load;
  if bad <> 0
     or missing <> 0
     or distinct_sailors <> 131
     or (select count(*) from public._rmor2025_load where fleet = 'Gold') <> 80
     or (select count(*) from public._rmor2025_load where fleet = 'Silver') <> 51 then
    raise exception 'Raffles Marina Optimist 2025 import failed: bad %, missing %, distinct %, gold %, silver %',
      bad, missing, distinct_sailors,
      (select count(*) from public._rmor2025_load where fleet = 'Gold'),
      (select count(*) from public._rmor2025_load where fleet = 'Silver');
  end if;
end $$;

delete from public.regatta_results result
using public.regattas regatta
where result.regatta_id = regatta.id
  and regatta.slug in (
    'raffles-marina-optimist-2025-gold',
    'raffles-marina-optimist-2025-silver',
    'rm-gold-jul-25-2025-07-05',
    'rm-silver-jul-25-2025-07-05'
  );

delete from public.regattas
where slug in ('rm-gold-jul-25-2025-07-05', 'rm-silver-jul-25-2025-07-05');

update public.regattas
set total_fleet_size = case division when 'Gold' then 80 else 51 end,
    race_count = case division when 'Gold' then 8 else 6 end,
    geography = 'SGP',
    schedule_notes = case division
      when 'Gold' then 'Raffles Marina Optimist Regatta 2025 Gold Fleet, 5-6 July 2025. Eight races completed; best seven count. Provisional results 6 July 2025.'
      else 'Raffles Marina Optimist Regatta 2025 Silver Fleet, 5-6 July 2025. Six races completed; best five count. Provisional results 6 July 2025.'
    end,
    status = 'published',
    counts_for_ranking = true,
    updated_at = now()
where slug in ('raffles-marina-optimist-2025-gold', 'raffles-marina-optimist-2025-silver');

  sailor_id, regatta_id, rank, nett_score, total_score, is_dns, is_overseas_commitment,
  gender, nationality, birth_year, evidence_name, evidence_type, evidence_notes,
  verification_status, verified_at, created_at, updated_at
)
select
  source.sailor_id,
  regatta.id,
  source.final_rank,
  source.nett,
  source.total,
  false,
  false,
  source.sex,
  sailor.nationality,
  extract(year from sailor.dob)::integer,
  case source.fleet
    when 'Silver' then 'Silver Fleet Results.pdf'
    else 'Gold Fleet Results.pdf'
  end,
  'pdf',
  case source.fleet
    when 'Silver' then 'Official Sailwave provisional results, 6 July 2025. Six races, one discard.'
    else 'Official Sailwave provisional results, 6 July 2025. Eight races, one discard.'
  end,
  'verified',
  now(),
  now(),
  now()
from public._rmor2025_load source
join public.sailors sailor on sailor.id = source.sailor_id
join public.regattas regatta on regatta.slug = case source.fleet
  when 'Silver' then 'raffles-marina-optimist-2025-silver'
  else 'raffles-marina-optimist-2025-gold'
end;

  regatta_result_id, race_number, score, scoring_code, discarded, raw_value, created_at, updated_at
)
select
  result.id,
  race.ordinality::integer,
  (race.item->>'score')::real,
  nullif(race.item->>'code', ''),
  (race.item->>'discarded')::boolean,
  race.item->>'raw',
  now(),
  now()
from public._rmor2025_load source
join public.regattas regatta on regatta.slug = case source.fleet
  when 'Silver' then 'raffles-marina-optimist-2025-silver'
  else 'raffles-marina-optimist-2025-gold'
end
join public.regatta_results result
  on result.regatta_id = regatta.id and result.sailor_id = source.sailor_id
cross join lateral jsonb_array_elements(source.races) with ordinality as race(item, ordinality);

update public.sailors sailor
set gender = source.sex, updated_at = now()
from public._rmor2025_load source
where sailor.id = source.sailor_id and sailor.gender is null;

drop table public._rmor2025_load;
